   154	/**
   155	 * gnutls_ocsp_req_print:
   156	 * @req: The data to be printed
   157	 * @format: Indicate the format to use
   158	 * @out: Newly allocated datum with (0) terminated string.
   159	 *
   160	 * This function will pretty print a OCSP request, suitable for
   161	 * display to a human.
   162	 *
   163	 * If the format is %GNUTLS_OCSP_PRINT_FULL then all fields of the
   164	 * request will be output, on multiple lines.
   165	 *
   166	 * The output @out->data needs to be deallocate using gnutls_free().
   167	 *
   168	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   169	 *   negative error value.
   170	 **/
   171	int
   172	gnutls_ocsp_req_print(gnutls_ocsp_req_t req,
   173	                      gnutls_ocsp_print_formats_t format,
   174	                      gnutls_datum_t * out)
   175	{
   176	        gnutls_buffer_st str;
   177	        int rc;
   178	
   179	        if (format != GNUTLS_OCSP_PRINT_FULL) {
   180	                gnutls_assert();
   181	                return GNUTLS_E_INVALID_REQUEST;
   182	        }
   183	
   184	        _gnutls_buffer_init(&str);
   185	
   186	        _gnutls_buffer_append_str(&str, _("OCSP Request Information:\n"));
   187	
   188	        print_req(&str, req);
   189	
   190	        rc = _gnutls_buffer_to_datum(&str, out, 1);
   191	        if (rc != GNUTLS_E_SUCCESS) {
   192	                gnutls_assert();
   193	                return rc;
   194	        }
   195	
   196	        return GNUTLS_E_SUCCESS;
   197	}
