   573	                                        addf(str, "error: crt_print: %s\n",
   574	                                             gnutls_strerror(ret));
   575	                                else {
   576	                                        addf(str, "%.*s", out.size,
   577	                                             out.data);
   578	                                        gnutls_free(out.data);
   579	                                }
   580	
   581	                                ret =
   582	                                    gnutls_x509_crt_export(certs[i],
   583	                                                           GNUTLS_X509_FMT_PEM,
   584	                                                           NULL, &s);
   585	                                if (ret != GNUTLS_E_SHORT_MEMORY_BUFFER)
   586	                                        addf(str,
   587	                                             "error: crt_export: %s\n",
   588	                                             gnutls_strerror(ret));
   589	                                else {
   590	                                        out.data = gnutls_malloc(s);
   591	                                        if (out.data == NULL)
   592	                                                addf(str,
   593	                                                     "error: malloc: %s\n",
   594	                                                     gnutls_strerror
   595	                                                     (GNUTLS_E_MEMORY_ERROR));
   596	                                        else {
   597	                                                ret =
   598	                                                    gnutls_x509_crt_export
   599	                                                    (certs[i],
   600	                                                     GNUTLS_X509_FMT_PEM,
   601	                                                     out.data, &s);
   602	                                                if (ret < 0)
   603	                                                        addf(str,
   604	                                                             "error: crt_export: %s\n",
   605	                                                             gnutls_strerror
   606	                                                             (ret));
   607	                                                else {
   608	                                                        out.size = s;
   609	                                                        addf(str, "%.*s",
   610	                                                             out.size,
   611	                                                             out.data);
   612	                                                }
   613	                                                gnutls_free(out.data);
   614	                                        }
   615	                                }
   616	
   617	                                gnutls_x509_crt_deinit(certs[i]);
   618	                        }
   619	                        gnutls_free(certs);
   620	                }
   621	        }
   622	}
