   624	/**
   625	 * gnutls_ocsp_resp_print:
   626	 * @resp: The data to be printed
   627	 * @format: Indicate the format to use
   628	 * @out: Newly allocated datum with (0) terminated string.
   629	 *
   630	 * This function will pretty print a OCSP response, suitable for
   631	 * display to a human.
   632	 *
   633	 * If the format is %GNUTLS_OCSP_PRINT_FULL then all fields of the
   634	 * response will be output, on multiple lines.
   635	 *
   636	 * The output @out->data needs to be deallocate using gnutls_free().
   637	 *
   638	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   639	 *   negative error value.
   640	 **/
   641	int
   642	gnutls_ocsp_resp_print(gnutls_ocsp_resp_t resp,
   643	                       gnutls_ocsp_print_formats_t format,
   644	                       gnutls_datum_t * out)
   645	{
   646	        gnutls_buffer_st str;
   647	        int rc;
   648	
   649	        _gnutls_buffer_init(&str);
   650	
   651	        _gnutls_buffer_append_str(&str, _("OCSP Response Information:\n"));
   652	
   653	        print_resp(&str, resp, format);
   654	
   655	        rc = _gnutls_buffer_to_datum(&str, out, 1);
   656	        if (rc != GNUTLS_E_SUCCESS) {
   657	                gnutls_assert();
   658	                return rc;
   659	        }
   660	
   661	        return GNUTLS_E_SUCCESS;
   662	}
